import{_ as t,o as i,c as e,a5 as n}from"./chunks/framework.CsGesDJn.js";const o=JSON.parse('{"title":"Media Package và Campaign","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/README.md","filePath":"feature/media-package-campaign/README.md"}'),h={name:"feature/media-package-campaign/README.md"};function c(r,a,g,d,p,l){return i(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="media-package-va-campaign" tabindex="-1">Media Package và Campaign <a class="header-anchor" href="#media-package-va-campaign" aria-label="Permalink to &quot;Media Package và Campaign&quot;">​</a></h1><h2 id="spec-hien-hanh" tabindex="-1">Spec hiện hành <a class="header-anchor" href="#spec-hien-hanh" aria-label="Permalink to &quot;Spec hiện hành&quot;">​</a></h2><p>BA chốt ngày 2026-11-05 nằm tại <a href="./guest-sharing-manager-led/spec.html">Guest sharing và hành trình do Manager quản lý</a>. Đây là đặc tả cho đợt thay đổi tiếp theo. Code, API/DB contract, migration và bằng chứng kiểm thử cũ cần được đánh giá khi lập plan triển khai.</p><ul><li>Owner quản lý gói quảng bá của Agency, xuất ảnh/PDF hoặc chia sẻ link guest.</li><li>Guest xem không cần tài khoản. Owner chia sẻ gói Agency; Manager phụ trách/Owner có quyền quản lý cũng chia sẻ được Custom Package workspace. Cùng một link luôn hiển thị bản mới nhất đã lưu của đúng gói được chia sẻ; hỗ trợ xuất ảnh/PDF cho cả hai phạm vi.</li><li>Owner tạo workspace và gán Manager trước khi có Client. Manager thống nhất gói với Client bên ngoài hệ thống.</li><li>Manager chọn gói Agency để tùy chỉnh hoặc tạo gói workspace mới. Lưu gói hợp lệ tự tạo một Campaign DRAFT và task lớn theo gói.</li><li>Client được mời vào để xem gói đã ghi nhận, xem Campaign và comment góp ý cả khi còn DRAFT.</li><li>Luồng mới bỏ Client chọn/đàm phán/duyệt gói và bỏ duyệt Campaign hai phía.</li><li>Manager sửa gói trước triển khai, đồng bộ kế hoạch/task có kiểm soát. Bản gói/kế hoạch được cố định khi triển khai và khóa sau triển khai.</li><li>Manager chủ động triển khai khi đủ điều kiện. Thành viên bắt đầu thực hiện khi Campaign IN_PROGRESS.</li></ul><p>Một workspace tiếp tục có một Campaign. Duyệt kết quả Task/bài đăng, xuất bản, Content Request và điều kiện đóng Campaign theo các spec riêng.</p><h2 id="tai-lieu-đoi-chieu" tabindex="-1">Tài liệu đối chiếu <a class="header-anchor" href="#tai-lieu-đoi-chieu" aria-label="Permalink to &quot;Tài liệu đối chiếu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nội dung</th><th>Tài liệu</th></tr></thead><tbody><tr><td>Quy tắc BA chung</td><td><a href="./../../ba/04-media-package-campaign.html">04-media-package-campaign.md</a></td></tr><tr><td>Workspace và thời điểm mời Client</td><td><a href="./../../ba/01-organization-structure.html">01-organization-structure.md</a></td></tr><tr><td>Vòng đời Package/Campaign</td><td><a href="./../../ba/12-state-machines.html">12-state-machines.md</a></td></tr><tr><td>Tạo gói Agency, lưu gói workspace</td><td><a href="./3-5-1-create-media-package/spec.html">FR 3.5.1</a></td></tr><tr><td>Guest view và Client xem gói</td><td><a href="./3-5-2-view-the-template-media-package/spec.html">FR 3.5.2</a></td></tr><tr><td>Chốt ngoài hệ thống, chỉnh trước triển khai</td><td><a href="./3-5-3-request-media-package/spec.html">FR 3.5.3</a></td></tr><tr><td>Thay flow duyệt Package</td><td><a href="./3-5-4-approve-media-package/spec.html">FR 3.5.4</a></td></tr><tr><td>Campaign DRAFT từ gói</td><td><a href="./3-5-5-create-media-campaign/spec.html">FR 3.5.5</a></td></tr><tr><td>Góp ý, triển khai và bỏ duyệt Campaign</td><td><a href="./3-5-6-approve-media-campaign/spec.html">FR 3.5.6</a></td></tr><tr><td>Task/subtask từ gói</td><td><a href="./../package-driven-campaign-tasks/spec.html">Package-driven campaign tasks</a></td></tr><tr><td>Hoàn thành Campaign</td><td><a href="./campaign-closure/spec.html">Campaign closure</a></td></tr></tbody></table><h2 id="pham-vi-tai-lieu-cu" tabindex="-1">Phạm vi tài liệu cũ <a class="header-anchor" href="#pham-vi-tai-lieu-cu" aria-label="Permalink to &quot;Phạm vi tài liệu cũ&quot;">​</a></h2><p>Các plan, task, test, sequence/class diagram, offering-models, phase-1-design, remaining-work và roadmap trước ngày 2026-11-05 lưu bối cảnh triển khai cũ. Những đoạn yêu cầu Client chọn gói, thương lượng/duyệt Package hai phía, duyệt Campaign hoặc khóa theo APPROVED đã được spec mới thay thế trong phạm vi nêu trên.</p><p>Không dùng kết quả kiểm thử hay trạng thái Implemented của flow cũ để xác nhận flow mới đã hoàn thành. Đợt hiện tại chỉ cập nhật spec và BA liên quan. Khi triển khai cần cập nhật lần lượt plan, task và test, xác định ảnh hưởng lên quyền truy cập, endpoint, dữ liệu cũ và các module liên quan.</p><p>Các điểm còn thuộc bước thiết kế kỹ thuật được liệt kê ở mục 11 của spec mới. Không tự chuyển đổi approval/historical data hoặc tạo lượt duyệt giả cho Client.</p>',11)])])}const s=t(h,[["render",c]]);export{o as __pageData,s as default};
